const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=['search','sport','type','role','evidence','radius','channel','fit','feasibility','level','coverage'];
const sections=['Leads','Followup','Clients','Reports','Delisted'];
const channelOrder=['Google Maps','Instagram','TikTok','Facebook','Schools & official data','Community directory','Organisation websites','Activity platforms'];
let D,leads=[],state=Object.fromEntries(new URLSearchParams(location.search)),section=({"Follow-up":'Followup',Calendar:'Clients',Results:'Reports',Channels:'Channels'})[state.section]||(sections.includes(state.section)?state.section:'Leads'),view=state.view||'Map',month=/^\d{4}-\d{2}$/.test(state.month||'')?state.month:new Date().toISOString().slice(0,7),selectedMap=state.map||null,returnFocus=null;
const captions={Leads:'Explore the local object library. Relevance is a research judgement, not confirmed demand.',Channels:'See available source entry points and the work actually completed for each channel.','Follow-up':'Only leads you have actively selected or recorded contact with. Research suggestions do not enter this queue.',Calendar:'Published event dates and undated activity windows. No follow-up deadlines have been assigned.',Results:'Geographic coverage, relevance and evidence — separate from commercial results.'};
