function safeURL(u){try{const p=new URL(u);return ['https:','http:'].includes(p.protocol)?p.href:'#'}catch{return '#'}}
function anchor(u,text,cls=''){return `<a class="${cls}" href="${esc(safeURL(u))}" target="_blank" rel="noopener">${esc(text)} ↗</a>`}
function sync(){const p=new URLSearchParams({section,view,month});for(const k of fields)if($(k).value)p.set(k,$(k).value);if($('detail').open&&$('detail').dataset.id)p.set('lead',$('detail').dataset.id);if($('detail').open&&state.detailTab)p.set('detailTab',state.detailTab);if(selectedMap)p.set('map',selectedMap);history.replaceState(null,'','?'+p)}
function baseFiltered(){return leads.filter(l=>{const r=$('role').value,rad=$('radius').value;return(r==='all'||(r?l.role===r:l.role!=='Competition reference'))&&(!rad||rad==='all'||(['pending','outside'].includes(rad)?l.scope===rad:l.distance_km!=null&&l.distance_km<=+rad))&&(!$('sport').value||l.sport.includes($('sport').value))&&(!$('type').value||l.type===$('type').value)&&(!$('evidence').value||l.read===$('evidence').value)&&(!$('channel').value||l.channels[$('channel').value])&&(!$('feasibility').value||RTMaps.classify(l).level===$('feasibility').value)&&(!$('fit').value||l.fit_group===$('fit').value)&&(!$('search').value||[l.name,l.address,l.type,l.fact,l.next].join(' ').toLowerCase().includes($('search').value.toLowerCase()))})}
function relevant(l){return l.fit_group==='Direct sport activity'?0:l.fit_group==='Relevant category'?1:2}
