function channelTags(l){return Object.keys(l.channels).map(c=>`<span class="tag">${esc(c)}</span>`).join('')}
function baseCard(l){return `<article class="card"><button class="name" data-id="${esc(l.id)}">${esc(l.name)}</button><small>${esc(dist(l))} · ${esc(l.address)}</small>${tags(l)}<p>${esc(l.match)}</p><small>${l.role==='Competition reference'?'Reference only':'V0 · No qualified opportunity'}</small><p><strong>Next:</strong> ${esc(l.next)}</p></article>`}
function baseTable(ls){return ls.length?`<div class="tablewrap leads-table"><table><thead><tr><th>Name / relevance</th><th>Distance / location</th><th>Channels</th><th>Demand evidence</th><th>Next research step</th></tr></thead><tbody>${ls.map(l=>`<tr><td><button class="name" data-id="${esc(l.id)}">${esc(l.name)}</button>${tags(l)}<small>${esc(l.role)} · ${l.qualification||'Reference only'}</small></td><td><strong>${esc(dist(l))}</strong><small>${esc(l.address)}</small></td><td>${channelTags(l)}</td><td class="signal">${l.signal?`<span class="tag">${esc(l.signal)}</span>`:'No court demand verified'}<small>${esc(l.fact)}</small></td><td class="signal">${esc(l.next)}<small>Owner: Unassigned · Due: Unknown</small></td></tr>`).join('')}</tbody></table></div><div class="mobilecards">${ls.map(card).join('')}</div>`:'<div class="empty"><h3>No matching objects</h3><p>Change the filters or reset to the 10 km library.</p></div>'}
function channelStatus(c){return ({'Google Maps':['Navigation only','Source coordinates were used for radius checks. Links open address searches; individual business listings were not scanned.'],'Instagram':['Profile links only','Profiles referenced by public organisation pages. Posts, activity dates and demand not reviewed.'],'Facebook':['Profile / group links only','Council-listed organisation profiles and groups. No post review or private-group access.'],'TikTok':['Access blocked','No verified accounts or videos in this research. No platform-scan claim.'],'Schools & official data':['2025 dataset read','All retained school rows have open status in the 2025 register. Current operations and additional campuses remain unverified.'],'Community directory':['Directory read','All 116 Kingston directory records processed; missing pins and inaccessible details retained separately.'],'Organisation websites':['Mixed reading states','Includes directly read pages, search excerpts and website links listed in directories. Open a record for exact evidence.'],'Activity platforms':['Search excerpts','Existing event and organiser listings retained. No current court-hire demand has been established.']})[c]}
function channelsView(){const scope=leads.filter(l=>RTCRM.visible(l)&&l.scope==='inside'&&l.role!=='Competition reference');return `<div class="notice">Counts are unique objects with an entry point in each channel, within 10 km. Channels overlap and must not be added together. A profile link is not a demand signal.</div><div class="channel-grid">${channelOrder.map(c=>{const n=scope.filter(l=>l.channels[c]).length,[status,note]=channelStatus(c);return `<article class="card"><div class="channel-head"><h3>${esc(c)}</h3><strong>${n}</strong></div><span class="tag">${esc(status)}</span><p>${esc(note)}</p><button data-channel="${esc(c)}">View ${n} objects</button></article>`}).join('')}</div><h2>Research boundary</h2><p>Badminton and pickleball acquisition around Rainbow Town, Braeside. Public-school data covers the radius across council boundaries; the community-directory import covers Kingston only. Businesses and social channels are not exhaustive.</p>`}
function resultsView(){const c=liveCounts(),inside=leads.filter(l=>RTCRM.visible(l)&&l.scope==='inside'&&l.role!=='Competition reference'),types={};inside.forEach(l=>types[l.type]=(types[l.type]||0)+1);return `<div class="cards"><article class="card"><h3>${c.inside_relevant} relevant-category objects</h3><p>Schools, activity groups and direct sport organisers. Relevance does not establish a court requirement.</p></article><article class="card"><h3>${c.inside_exploratory} exploratory objects</h3><p>Weaker fit or age suitability unresolved. Retained for review and excluded from any claim of qualified demand.</p></article><article class="card"><h3>Commercial results unavailable</h3><p>No booking, payment, attendance or repeat-visit records supplied. No revenue or conversion rate inferred.</p></article></div><h2>Within 10 km · by type</h2><div class="tablewrap"><table><thead><tr><th>Object type</th><th>Unique objects</th></tr></thead><tbody>${Object.entries(types).sort((a,b)=>b[1]-a[1]).map(([t,n])=>`<tr><td>${esc(t)}</td><td>${n}</td></tr>`).join('')}</tbody></table></div><h2>Business milestones</h2><p>All candidate objects remain V0. V1 requires a specific need, fit and owner confirmation; V2 requires relevant interest in Rainbow Town; V3 requires a verified agreement or attributable payment. No such opportunity has been established.</p>`}
function calendarView(ls){const [y,m]=month.split('-').map(Number),n=new Date(Date.UTC(y,m,0)).getUTCDate(),offset=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7,events=ls.filter(l=>l.date?.startsWith(month));return `<div class="monthbar"><button data-month="-1" aria-label="Previous month">←</button><strong>${esc(month)}</strong><button data-month="1" aria-label="Next month">→</button><span class="tag">Event dates · source listings</span></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div>${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="day muted"></div>').join('')}${Array.from({length:n},(_,i)=>{const day=month+'-'+String(i+1).padStart(2,'0');return `<div class="day">${i+1}${events.filter(l=>l.date===day).map(l=>`<button data-id="${l.id}">${esc(l.name)}<small>Needs confirmation</small></button>`).join('')}</div>`}).join('')}</div>${events.length?'':'<p>No dated events in the current month and filters.</p>'}<h2>Unknown or recurring windows</h2><div class="cards">${ls.filter(l=>l.signal&&!l.date).map(card).join('')||'<p>No undated activity signals in this selection.</p>'}</div><p>Follow-up deadlines are unknown. Recurring descriptions are not converted into invented event dates.</p>`}
function mapView(ls){const located=ls.filter(l=>l.lat!=null&&l.lon!=null);const counts={high:0,medium:0,low:0,reference:0};located.forEach(l=>{const k=RTMaps.classify(l).level;counts[k]=(counts[k]||0)+1});return `<div class="map-legend"><span class="priority-badge high">Red · High ${counts.high}</span><span class="priority-badge medium">Orange · Medium ${counts.medium}</span><span class="priority-badge low">Green · Low ${counts.low}</span><span class="priority-badge venue">R · Rainbow Town</span><button id="fit-map">Show all points</button></div><details class="map-rules"><summary>How feasibility is assessed</summary><p>Red: published racket-sport activity, or a relevant category within 3 km with a public contact route. Orange: relevant category with more suitability checks needed. Green: exploratory / weaker fit. Grey: no collected contact route, competition or outside-radius reference. Manual five-colour stars override the reference colour, but do not change evidence credibility.</p><p>Research priority only, not a conversion probability or confirmed booking. Source locations may be offices or historical activity venues. Objects without supported coordinates are not given invented pins.</p></details><p id="map-status" role="status">${located.length?'Loading Google Maps…':'No supported coordinates in these filters. Use List to review address-only records.'}</p><div class="maparea"><div id="google-map" aria-label="Google map of candidate organisations" ${located.length?'':'hidden'}></div><div class="maplist">${located.map(x=>{const p=RTMaps.classify(x);return `<article class="card"><button class="name" data-map="${x.id}">${esc(x.name)}</button><span class="priority-badge ${p.level}">${esc(p.label)}</span><small>${dist(x)} · ${esc(x.address)}</small><button data-id="${x.id}">View evidence</button></article>`}).join('')}</div></div>`}
function highlightMap(id){selectedMap=id;sync();document.querySelectorAll('[data-map]').forEach(b=>b.classList.toggle('selected',b.dataset.map===id))}

function render(){if(!D)return;const ls=filtered(),c=liveCounts();workspaceStatus();$('title').textContent=section;$('intro').textContent=captions[section];document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.section===section);b.setAttribute('aria-current',b.dataset.section===section?'page':'false')});$('stats').innerHTML=[[c.inside,'Objects within 10 km'],[c.inside_relevant,'Relevant category · still V0'],[c.pending,'Candidates · location pending'],['—','Bookings / revenue not connected']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('');$('controls').hidden=['Channels','Results'].includes(section);$('export').hidden=['Channels','Results'].includes(section);$('views').innerHTML='';if(['Leads','Calendar'].includes(section))for(const v of ['Everything','List','Latest signals','Map','Calendar']){const b=document.createElement('button');b.textContent=v;b.classList.toggle('selected',view===v);b.setAttribute('aria-pressed',view===v);b.onclick=()=>{view=v;sync();render()};$('views').append(b)}$('count').textContent=`${ls.length} unique objects in current filters`;
if(section==='Channels'){$('content').innerHTML=channelsView();$('count').textContent='8 channel groups · overlapping coverage'}else if(section==='Results'){$('content').innerHTML=resultsView();$('count').textContent='Full reviewed library'}else if(section==='Follow-up'){const fs=ls.filter(l=>RTCRM.get(l.id).follow);$('count').textContent=`${fs.length} active follow-ups`;$('content').innerHTML=fs.length?`<div class="cards">${fs.map(card).join('')}</div>`:'<div class="empty"><h3>No active follow-ups</h3><p>Open a lead and choose Follow up, or record a contact action you have actually completed.</p></div>';}else if(view==='Calendar'){$('content').innerHTML=calendarView(ls)}else if(view==='Map'){$('content').innerHTML=mapView(ls)}else if(view==='Latest signals'){const ss=ls.filter(l=>l.signal);$('count').textContent=`${ss.length} activity / change records in current filters`;$('content').innerHTML=`<div class="notice">Organised play and membership pressure are research clues. None establishes a request for Rainbow Town courts.</div><div class="cards">${ss.map(card).join('')||'<p>No activity signals in these filters.</p>'}</div>`}else if(view==='Everything')$('content').innerHTML=`<div class="cards photo-cards">${ls.map(card).join('')}</div>`;else $('content').innerHTML=table(ls);
if(view==='Map'&&['Leads','Calendar'].includes(section)){const located=ls.filter(l=>l.lat!=null&&l.lon!=null);if(located.length)RTMaps.draw({element:$('google-map'),rows:located,center:D.center,onSelect:highlightMap,onDetail:openDetail});$('fit-map').onclick=()=>RTMaps.fit();}
bindWorkspace();$('content').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id));$('content').querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{resetFields();$('channel').value=b.dataset.channel;section='Leads';view='List';sync();render()});$('content').querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{highlightMap(b.dataset.map);RTMaps.select(b.dataset.map)});$('content').querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{const [y,m]=month.split('-').map(Number),date=new Date(Date.UTC(y,m-1+Number(b.dataset.month),1));month=date.toISOString().slice(0,7);sync();render()})}
function baseOpenDetail(id){const l=leads.find(l=>l.id===id);if(!l)return;returnFocus=document.activeElement;$('detail').dataset.id=id;$('detailbody').innerHTML=`<h2>${esc(l.name)}</h2>${tags(l)}<p>${esc(l.role)} · ${esc(l.sport)}</p><div class="notice">${l.role==='Competition reference'?'Competition reference · not a customer count':'V0 collected object · no qualified opportunity established.'}</div><dl><dt>Distance</dt><dd>${esc(dist(l))}<small>${esc(l.scope_reason||'Within the requested 10 km straight-line radius.')}</small></dd><dt>Location</dt><dd>${esc(l.address)}<small>${esc(l.locationRole)}<br>${esc(l.geo_evidence)}</small></dd><dt>Owner / due</dt><dd>Unassigned / Unknown</dd><dt>Checked</dt><dd>${D.checked_at}<small>School data is a 2025 snapshot where applicable.</small></dd></dl><h3>Published facts</h3><p>${esc(l.fact)}</p><small>Activity validity: ${esc(l.valid)} · ${esc(l.window)}</small><h3>Feasibility · research assessment</h3><span class="priority-badge ${RTMaps.classify(l).level}">${esc(RTMaps.classify(l).label)}</span><p>${esc(RTMaps.classify(l).reason)}</p><h3>Potential fit · research inference</h3><p>${esc(l.match)}</p><h3>Unknowns</h3><p>${esc(l.unknown)}</p><h3>Next research step</h3><p>${esc(l.next)}</p><h3>Public contact</h3>${l.contact_name?`<p>${esc(l.contact_name)}<small>Listed contact; decision-making role unverified</small></p>`:''}<p>${l.phones.map(p=>esc(p)).join('<br>')||'No verified telephone in the selected contact field.'}</p><p>${l.emails.map(p=>esc(p)).join('<br>')}</p>${l.legacy_contact&&!l.phones.length?`<p>${esc(l.legacy_contact)}<small>Earlier source contact; reconfirm before use.</small></p>`:''}<small>${esc(l.contact_note)}</small><h3>Channels</h3>${Object.entries(l.channels).map(([k,v])=>`<div class="source"><strong>${esc(k)}</strong>${v.map(x=>`<p>${anchor(x.url,k)}</p><small>${esc(({address_search:'Address search link only · not an independently checked Google listing',directory_link:'Profile/group linked by organisation directory · posts not reviewed',listed_link:'Website linked by directory · destination not checked',read_source:'Original source read; see stated facts below',search_excerpt:'Search excerpt only; full content not verified',unavailable:'Source could not be read'})[x.evidence_kind]||x.evidence_kind)}</small>`).join('')}</div>`).join('')}<h3>Source evidence</h3>${l.sources.map(s=>`<div class="source">${anchor(s.url,s.label)}<small>${reading(s.reading_state)} · ${esc(s.note)}</small></div>`).join('')}<h3>Opportunities and activity</h3><p>No qualified opportunity, reply, booking, agreement or payment has been supplied. Actual contact actions, if any, are recorded in My lead management above.</p>`;if(!$('detail').open)$('detail').showModal();sync()}
function resetFields(){for(const k of fields)$(k).value=k==='radius'?'10':''}
function method(){if($('detail-actions'))$('detail-actions').hidden=true;returnFocus=document.activeElement;$('detail').dataset.id='';$('detailbody').innerHTML=`<h2>Coverage & review</h2><p>Centre: ${esc(D.center.address)}. Source pin: ${D.center.lat}, ${D.center.lon}. Haversine straight-line distances are filtered before rounding.</p><h3>What changed in this review</h3><ul><li>Removed council-footer phone contamination and extracted each organisation’s contact block.</li><li>Retained 123 school-register records after checking their 2025 status; same-name schools at different addresses remain distinct.</li><li>Merged four school/community records and two businesses with the original research.</li><li>Separated relevant categories from weaker exploratory fit; no commercial qualification was inferred.</li><li>Kept map navigation, listed social profiles and read source evidence distinct.</li></ul><h3>Coverage gaps</h3><ul>${D.review.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><h3>Counts and exclusions</h3><p>${D.review.counts.inside} within-radius objects, ${D.review.counts.pending} candidate locations pending, ${D.review.counts.outside} outside-radius records and ${D.review.counts.competition} competition references. Channel counts overlap.</p><h3>School source attribution</h3><p>Victorian Department of Education, School Locations 2025, published 29 August 2025, CC BY 4.0. Distances and relevance groupings are derived research.</p>${anchor('https://discover.data.vic.gov.au/dataset/school-locations-2025','Source dataset')}<h3>Venue conditions to confirm</h3><p>Available times, rates, existing organiser relationships, equipment and group services must be confirmed before making offers. Public capacity descriptions differ; no capacity or court-hour promise is inferred here.</p>`;$('detail').showModal()}
async function init(){try{const response=await fetch('research.json');if(!response.ok)throw new Error('Research data unavailable');D=await response.json();await RTCRM.load();leads=D.entities;for(const n of sections){const b=document.createElement('button');b.textContent=n;b.dataset.section=n;b.onclick=()=>{section=n;view='List';resetFields();$('radius').value=n==='Clients'||n==='Followup'?'all':'10';sync();render()};$('nav').append(b)}for(const t of [...new Set(leads.map(l=>l.type))].sort())$('type').add(new Option(t,t));for(const c of channelOrder)$('channel').add(new Option(c,c));for(const k of fields){$(k).value=state[k]??(k==='radius'?'10':'');if($(k).selectedIndex===-1&&k==='radius')$(k).value='10';$(k).addEventListener(k==='search'?'input':'change',()=>{sync();render()})}$('close').onclick=()=>$('detail').close();$('detail').addEventListener('close',()=>{delete $('detail').dataset.id;sync();if(returnFocus?.isConnected)returnFocus.focus()});$('advanced-filters').onclick=()=>{const open=$('controls').classList.toggle('expanded');$('advanced-filters').setAttribute('aria-expanded',String(open));$('advanced-filters').textContent=open?'收起筛选':'更多筛选'};$('reset').onclick=()=>{resetFields();sync();render()};$('method').onclick=method;$('export').onclick=()=>{const blob=new Blob([JSON.stringify({checked_at:D.checked_at,center:D.center,filter:Object.fromEntries(fields.map(k=>[k,$(k).value])),entities:(section==='Followup'?filtered().filter(l=>RTCRM.get(l.id).follow):filtered()).map(l=>({...l,manual:RTCRM.get(l.id)})),opportunities:[],review:D.review},null,2)],{type:'application/json'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='rainbow-town-filtered-research.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();if(state.lead)openDetail(state.lead);if(navigator.modelContext?.registerTool){navigator.modelContext.registerTool({name:'read_rainbow_town_leads',description:'Read currently filtered public research without modifying records or contacting anyone.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async()=>({content:[{type:'text',text:JSON.stringify({checked_at:D.checked_at,entities:filtered(),opportunities:D.opportunities,connected:false})}]})})}}catch(e){$('content').innerHTML='<div class="empty"><h2>Research could not be loaded</h2><p>Refresh this page to retry.</p></div>';console.error(e)}}

